<script>
(function(){
  var _cs = document.currentScript;
  var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.createElementNS(NS,"svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  function el(tag, attrs, txt){
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (txt !== undefined) e.textContent = txt;
    return e;
  }
  function tw(s, fs){
    var w = 0;
    for (var c = 0; c < s.length; c++){
      var ch = s.charAt(c);
      w += (ch >= "A" && ch <= "Z") ? fs * 0.68 : fs * 0.58;
    }
    return Math.ceil(w);
  }
  function tx(s, a){ a["font-family"] = FONT; return el("text", a, s); }
  var data = [17.10,17.20,17.71,15.44,14.81,14.87,14.21,15.18,15.67,14.87,16.07,16.04,16.34,16.39,15.31,15.52,15.01,15.08,15.41,14.84,15.21,15.27];
  var dates = ["14 sept.","15 sept.","16 sept.","17 sept.","18 sept.","21 sept.","22 sept.","23 sept.","24 sept.","25 sept.","28 sept.","29 sept.","30 sept.","1er oct.","2 oct.","5 oct.","6 oct.","7 oct.","8 oct.","9 oct.","12 oct.","13 oct."];
  var xTicks = [0,3,6,9,12,15,18,21];
  var n = data.length;
  var margin = {left: 62, right: 24, top: 18, bottom: 46};
  var PW = 680 - margin.left - margin.right;
  var PH = 300 - margin.top - margin.bottom;
  var MT = margin.top;
  var lo = Math.min.apply(null, data), hi = Math.max.apply(null, data);
  var yMin = Math.floor(lo - 0.5), yMax = Math.ceil(hi + 0.5);
  function xp(i){ return margin.left + (i / (n - 1)) * PW; }
  function yp(v){ return margin.top + ((yMax - v) / (yMax - yMin)) * PH; }
  var currentVal = data[n - 1];
  var lastX = xp(n - 1), lastY = yp(currentVal);

  // band (background)
  var bandA = 10, bandB = 15;
  svg.appendChild(el("rect", {x: xp(bandA), y: margin.top, width: xp(bandB) - xp(bandA), height: PH, fill: "#c0392b", "fill-opacity": 0.05}));
  // gridlines
  for (var t = yMin; t <= yMax; t++){
    if (t === currentVal) continue;
    svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(t), y2: yp(t), stroke: "#ececec", "stroke-width": 0.5}));
  }
  // reference lines
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(hi), y2: yp(hi), stroke: "#2e7d32", "stroke-width": 1, "stroke-dasharray": "3,3"}));
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(lo), y2: yp(lo), stroke: "#7a3030", "stroke-width": 1, "stroke-dasharray": "3,3"}));
  // series
  var d = "";
  for (var i = 0; i < n; i++) d += (i === 0 ? "M" : "L") + xp(i).toFixed(1) + "," + yp(data[i]).toFixed(1);
  svg.appendChild(el("path", {d: d, fill: "none", stroke: "#4a5568", "stroke-width": 2, "stroke-linejoin": "round"}));
  // axis lines
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: margin.top + PH, y2: margin.top + PH, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: margin.top, y2: margin.top + PH, stroke: "#d8d8d8", "stroke-width": 1}));
  // events: lines then dots
  var events = [
    {i: 3, lines: ["17 sept.\u00a0: VIX", "-12,8\u00a0% en un jour"]},
    {i: 19, lines: ["9 oct.\u00a0: -68\u00a0300", "emplois, VIX -3,7\u00a0%"]}
  ];
  events.forEach(function(ev){
    var ex = xp(ev.i);
    svg.appendChild(el("line", {x1: ex, x2: ex, y1: margin.top, y2: margin.top + PH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
  });
  for (var j = 0; j < n - 1; j++) svg.appendChild(el("circle", {cx: xp(j), cy: yp(data[j]), r: 2, fill: "#4a5568"}));
  svg.appendChild(el("circle", {cx: lastX, cy: lastY, r: 4, fill: "#4a5568"}));
  // gold pill
  var pillText = currentVal.toFixed(2).replace(".", ",");
  var pillW = tw(pillText, 9) + 10;
  var pillH = 16;
  var pillX = lastX - pillW - 6;
  var pillY = lastY - pillH / 2;
  if (pillX < margin.left) pillX = margin.left;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(tx(pillText, {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3, "text-anchor": "middle", "font-size": 9, "font-weight": 700, fill: "#111111"}));
  // y labels
  for (var u = yMin; u <= yMax; u++){
    svg.appendChild(tx(String(u), {x: margin.left - 6, y: yp(u) + 3, "text-anchor": "end", "font-size": 8.5, fill: "#aaaaaa"}));
  }
  // x labels (single pass)
  xTicks.forEach(function(k){
    var last = (k === n - 1);
    svg.appendChild(tx(dates[k], {x: xp(k), y: margin.top + PH + 16, "text-anchor": last ? "end" : "middle", "font-size": 8, fill: "#999999"}));
  });
  // band label
  svg.appendChild(tx("12+ PÉTROLIERS VISÉS", {x: (xp(bandA) + xp(bandB)) / 2, y: margin.top + 10, "text-anchor": "middle", "font-size": 7, "font-weight": 700, fill: "#c0392b"}));
  // reference labels (suppressed when within 3% of the pill value)
  if (Math.abs(hi - currentVal) / currentVal >= 0.03) svg.appendChild(tx("SOMMET " + hi.toFixed(2).replace(".", ","), {x: margin.left + 10, y: yp(hi) - 10, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: "#2e7d32"}));
  if (Math.abs(lo - currentVal) / currentVal >= 0.03) svg.appendChild(tx("CREUX " + lo.toFixed(2).replace(".", ","), {x: margin.left + 10, y: yp(lo) + 12, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: "#7a3030"}));
  // event labels
  events.forEach(function(ev){
    var ex = xp(ev.i);
    var labelWidth = 0;
    ev.lines.forEach(function(L){ labelWidth = Math.max(labelWidth, tw(L, 7)); });
    var crowded = events.some(function(o){ return o.i !== ev.i && Math.abs(xp(o.i) - ex) < 85; });
    var nearRight = (ex + labelWidth + 3) > (margin.left + PW);
    var offset = crowded ? -40 : (nearRight ? -5 : 3);
    var anchor = (crowded || nearRight) ? "end" : "start";
    var yStart = crowded ? MT + 50 : MT + 20;
    ev.lines.forEach(function(L, li){
      svg.appendChild(tx(L, {x: ex + offset, y: yStart + li * 9, "text-anchor": anchor, "font-size": 7, "font-weight": 700, fill: "#1a3560"}));
    });
  });
  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: indice de volatilité Cboe, clôtures quotidiennes via Investing.com, 13 octobre 2026&nbsp;; rapports de Reuters et de l’UKMTO sur les pétroliers&nbsp;; Statistique Canada, 9 octobre 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">La bande ombragée marque la période du 28 septembre au 5 octobre, fenêtre où Reuters a dénombré au moins 12 attaques de pétroliers autour du détroit&nbsp;; le VIX a augmenté de 8,07&nbsp;% le 28 septembre. Source&nbsp;: Cboe via Investing.com.</p>
<h2>Les racines rationnelles du calme</h2>
<p>Le calme n’est pas purement psychologique. Le 6 octobre, l’indice S&amp;P 500 a atteint un sommet record alors que la probabilité d’une hausse de taux de la Réserve fédérale en octobre est tombée à environ 20&nbsp;%, contre près de 70&nbsp;% une semaine plus tôt, selon XTB, après la publication de données plus faibles sur le marché du travail américain. La même note chiffrait la croissance consensuelle des bénéfices du troisième trimestre de l’indice à plus de 30&nbsp;% sur un an. Les investisseurs réagissent à de l’information réelle.</p>
<p>Cela explique aussi la réaction aux données canadiennes. Statistique Canada a annoncé le 9 octobre que l’économie avait perdu 68&nbsp;300 emplois en septembre après en avoir perdu 41&nbsp;700 en août, et que le taux de chômage était passé à 6,5&nbsp;% contre 6,4&nbsp;%. Le VIX a reculé de 3,70&nbsp;% ce jour-là, à 14,84. Les données faibles se lisent maintenant comme un risque de taux moindre, un pari qui fonctionne jusqu’à ce que les données passent de faibles à désastreuses.</p>
<p>La question comportementale est ce qui se produit lorsque l’information va dans l’autre sens. Kahneman et Tversky, dans un article publié dans Econometrica en 1979, ont montré que les pertes pèsent plus lourd que des gains équivalents, et leurs estimations ultérieures situent le ratio près de deux pour un. Shlomo Benartzi et Richard Thaler, dans un article de 1995 du Quarterly Journal of Economics, ont relié l’ampleur de la prime de risque des actions aux investisseurs qui combinent cette aversion aux pertes et une évaluation fréquente de leur portefeuille, qu’ils estimaient à environ une fois par année.</p>
<h2>Pourquoi le point de bascule est la partie dangereuse</h2>
<p>Le calme laisse les investisseurs le moins préparés à une perte au moment où elle survient. Terrance Odean, qui a étudié environ 10&nbsp;000 comptes de courtage pour un article de 1998 du Journal of Finance, a constaté que les investisseurs réalisaient 14,8&nbsp;% de leurs gains théoriques mais seulement 9,8&nbsp;% de leurs pertes théoriques, soit l’effet de disposition. Brad Barber et Odean, dans un article de 2000 de la même revue, ont constaté que les ménages les plus actifs avaient obtenu 11,4&nbsp;% par an de 1991 à 1996, alors que le marché rapportait 17,9&nbsp;%.</p>
<p>Pour les portefeuilles canadiens, l’exposition se situe à deux endroits. Le TSX est pondéré en faveur de l’énergie, qui profite du risque d’approvisionnement que les marchés ont cessé de chiffrer, et des services financiers, qui portent le marché du travail et la trajectoire des taux dont la Banque du Canada se saisit le 28 octobre à 9 h 45 HE. Un choc dans un sens ou dans l’autre frapperait des investisseurs qui ont passé des semaines à apprendre que rien n’arrive.</p>
<p>Un VIX de 15,27 mesure ce que les marchés d’options facturent aujourd’hui pour une protection. Il ne dit rien de ce que le détroit d’Ormuz peut encore faire, et la recherche donne à penser que les décisions coûteuses se regroupent à la transition, lorsqu’une longue période de calme prend fin et que la première grosse perte frappe des gens qui avaient cessé d’en attendre une.</p>
',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients dont le portefeuille est largement investi en actions voient des écrans calmes et des soldes en hausse pendant que l’actualité décrit des attaques de pétroliers et un marché du travail qui s’affaiblit. Le sentiment dominant est un soulagement discret dont ils se méfient. Les clients qui suivent de près les manchettes ressentent l’écart entre ce qu’ils lisent et ce qu’ils voient, et beaucoup y voient le signe que quelque chose leur échappe. Les retraités qui tirent un revenu de leur portefeuille se sentent les plus exposés au jour où le calme prendra fin.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Je voulais vous appeler pendant que les marchés sont calmes, car c’est le meilleur moment pour parler du risque. Le marché est calme, avec l’indice de volatilité près de 15, même s’il y a eu des attaques répétées de pétroliers autour du détroit d’Ormuz et que le Canada a perdu 68&nbsp;300 emplois en septembre. Un tel calme est une information réelle, mais ce n’est pas une garantie. La recherche sur le comportement des investisseurs est constante&nbsp;: les erreurs coûteuses surviennent lorsqu’une longue période de calme prend fin et que la première grosse perte frappe des gens qui avaient cessé d’en attendre une. Votre plan suppose déjà que ces jours viendront. J’aimerais confirmer trois choses aujourd’hui. Premièrement, que votre réserve de liquidités couvre les douze prochains mois de retraits. Deuxièmement, que votre répartition en actions correspond toujours à ce que vous m’avez dit pouvoir tolérer dans une mauvaise année. Troisièmement, que nous convenions dès maintenant de ce que nous ferons, et ne ferons pas, si les marchés chutent fortement. Cela vous convient-il&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les retraités et préretraités qui puisent dans des portefeuilles à forte composante d’actions et détiennent moins de douze mois de retraits en liquidités ou en placements à court terme, et les clients qui ont augmenté leur exposition aux actions pendant la récente série de séances calmes.</p>
<p><strong>Incidence variable&nbsp;:</strong> les clients qui détiennent des positions concentrées dans l’énergie canadienne, qui profitent d’un pétrole élevé mais portent le risque lié aux manchettes géopolitiques, et les clients dont le revenu d’emploi est variable après les pertes d’emplois de septembre.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> les clients qui disposent d’un énoncé de politique de placement écrit et d’une réserve de liquidités financée, et qui peuvent rééquilibrer selon leur propre calendrier au lieu de réagir.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Repérer les clients dont les retraits des douze prochains mois ne sont pas couverts par des liquidités ou des placements à court terme.</div>
<div class="checklist-item">Sortir les comptes dont la pondération en actions a dépassé la cible pendant la récente remontée.</div>
<div class="checklist-item">Confirmer la tolérance au risque écrite de chaque client et la date de sa dernière révision.</div>
<div class="checklist-item">Signaler les clients qui détiennent des positions concentrées dans l’énergie canadienne.</div>
<div class="checklist-item">Consigner chaque appel au dossier du client, y compris la réaction convenue en cas de forte baisse.</div>
<div class="checklist-item">Prévoir une courte rencontre de suivi avant la décision de la Banque du Canada du 28 octobre.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Un marché calme est le bon moment pour confirmer le plan<br><br>
Bonjour [Nom du client],<br><br>
Merci d’avoir pris mon appel. Les marchés ont été calmes dernièrement, malgré des manchettes inquiétantes en provenance du détroit d’Ormuz et un faible rapport sur l’emploi de septembre au Canada. Les périodes de calme sont celles où il est le plus facile d’oublier que de fortes baisses surviennent, et la recherche montre que les plus grosses erreurs tendent à survenir juste après la fin d’une longue période de calme.<br><br>
Voici ce dont nous avons convenu&nbsp;: nous confirmerons que votre réserve de liquidités couvre les douze prochains mois de retraits prévus, nous vérifierons si votre pondération en actions est toujours celle que vous souhaitez, et nous suivrons le plan écrit plutôt que de réagir aux manchettes.<br><br>
Veuillez répondre avec un moment qui vous convient pour une révision de 20 minutes.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Investisseurs autonomes</strong> qui ont accru leur exposition aux actions pendant le récent calme et n’ont aucun plan écrit en cas de forte baisse. <strong>Retraités récents</strong> qui gèrent eux-mêmes leurs retraits et n’ont jamais tiré un revenu pendant un repli. <strong>Propriétaires d’entreprise</strong> dont les avoirs sont concentrés dans l’énergie ou les ressources canadiennes à l’extérieur de leur société. <strong>Ménages des secteurs touchés</strong> qui détiennent des comptes autogérés à forte composante d’actions après les 68&nbsp;300 pertes d’emplois de septembre.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Les marchés semblent exceptionnellement calmes compte tenu des manchettes en provenance du détroit d’Ormuz et du rapport sur l’emploi de vendredi dernier, et je discute avec des gens de ce que ce calme dit et ne dit pas. Auriez-vous quelques minutes&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Un marché calme est le moment où les investisseurs autonomes se sentent le plus capables et sont le moins préparés. La recherche sur la myopie face au désastre et l’effet de disposition est claire&nbsp;: les décisions coûteuses surviennent à la fin d’une longue période de calme, et la personne qui gère seule n’a personne à appeler ni plan rédigé à l’avance.</p>
<p>L’asymétrie est simple. Le client potentiel possède un portefeuille et un sentiment de confiance. Un conseiller apporte un plan documenté, une réserve de liquidités calibrée sur les retraits et une deuxième voix au moment où la première grosse perte survient.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<div class="checklist-item">Comment votre portefeuille s’est-il comporté au cours du dernier mois, et dans quelle mesure l’avez-vous surveillé&nbsp;?</div>
<div class="checklist-item">Si votre portefeuille perdait 15&nbsp;% en trois mois, que feriez-vous en premier&nbsp;?</div>
<div class="checklist-item">Cette réaction est-elle écrite, ou décideriez-vous sur le moment&nbsp;?</div>
<div class="checklist-item">Combien de mois de dépenses pourriez-vous couvrir sans vendre de placements&nbsp;?</div>
